public class Podcast implements Reproduzivel,VelocidadeAjustavel { private final String titulo; private final int duracao; private double velocidade=1.0; public Podcast(String t,int d){titulo=t;duracao=d;} public void reproduzir(){System.out.println("Podcast "+titulo+" em "+velocidade+"x");} public void pausar(){System.out.println("Pausando "+titulo);} public void avaliar(int n){if(n<1||n>5)throw new IllegalArgumentException("Nota 1..5");} public String getTitulo(){return titulo;} public int getDuracao(){return duracao;} public void setVelocidade(double v){if(!velocidadeValida(v))throw new IllegalArgumentException("Velocidade inválida");velocidade=v;} public double getVelocidade(){return velocidade;} }
